package me.albert.netsqueeze.client;

import io.netty.buffer.ByteBuf;
import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInboundHandlerAdapter;
import io.netty.handler.codec.CorruptedFrameException;
import io.netty.handler.codec.DecoderException;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;
import net.minecraft.network.CompressionDecoder;
import net.minecraft.network.HandlerNames;

/**
 * 挂在 splitter 前面(入站先经过它),两个阶段:
 * <ul>
 *   <li><b>切换前</b>:按原版的 varint 帧长自己切帧,一次只交给 splitter 一个完整帧(连长度前缀原样)。
 *       这样 splitter 手里永远不会攒着后面的字节,enable 那一帧交出去、{@link EnableDetector} 同步置位后,
 *       剩下的字节还在这里,直接按新格式解,不用从 splitter 里往回抢,也不用在别的解码器中途改管线。</li>
 *   <li><b>切换后</b>:帧格式和服务端 FrameDeflater 一致,varint 帧长 + deflate 输出(整条连接共用一个流、
 *       每帧 SYNC_FLUSH);解出来是一串"varint 包长 + 包字节",逐包从 decompress(没有就 splitter)的 context
 *       往下发,绕过 splitter 和原版逐包解压,直接进 decoder。</li>
 * </ul>
 * 服务端不认握手时,配置阶段结束由 EnableDetector 通知撤掉自己,之后零开销。全部在这条连接的 netty 线程上跑。
 */
final class StreamDecoder extends ChannelInboundHandlerAdapter {

    static final String NAME = "netsqueeze_inflate";

    /** 单帧压缩后上限;原版帧最大 2 MB(3 字节 varint),流式帧一 tick 一帧,正常远小于这个 */
    private static final int MAX_FRAME = 16 * 1024 * 1024;

    /** 单帧解压后上限,防坏流把内存撑爆 */
    private static final int MAX_INFLATED = 64 * 1024 * 1024;

    /** 每次 inflate 前至少留出这么多输出空间 */
    private static final int CHUNK = 8 * 1024;

    /** nowrap:服务端帧里不带 zlib 头和校验和 */
    private final Inflater inflater = new Inflater(true);

    private ByteBuf cumulation;
    private boolean streaming;
    private boolean enablePending;
    private boolean giveUpPending;
    private boolean removed;

    /** EnableDetector 在本线程同步调,等交出去的那一帧返回后才生效 */
    void enable() {
        this.enablePending = true;
    }

    void giveUp() {
        this.giveUpPending = true;
    }

    @Override
    public void channelRead(final ChannelHandlerContext ctx, final Object msg) throws Exception {
        if (!(msg instanceof ByteBuf in)) {
            ctx.fireChannelRead(msg);
            return;
        }
        if (this.cumulation == null) this.cumulation = ctx.alloc().buffer(in.readableBytes());
        this.cumulation.writeBytes(in);
        in.release();
        try {
            this.process(ctx);
        } catch (final DataFormatException e) {
            throw new DecoderException("NetSqueeze 解压失败", e);
        } finally {
            this.compact();
        }
    }

    @Override
    public void handlerRemoved(final ChannelHandlerContext ctx) {
        // 原生内存,连接关闭(netty 拆管线)或撤掉时都会走这里
        this.inflater.end();
        if (this.cumulation != null) {
            this.cumulation.release();
            this.cumulation = null;
        }
    }

    private void process(final ChannelHandlerContext ctx) throws DataFormatException {
        while (!this.removed && this.cumulation != null && this.cumulation.isReadable()) {
            final int start = this.cumulation.readerIndex();
            final int length = readVarInt(this.cumulation);
            if (length < 0 || this.cumulation.readableBytes() < length) {
                this.cumulation.readerIndex(start);
                return;
            }
            if (length > MAX_FRAME) throw new CorruptedFrameException("NetSqueeze 帧过大: " + length);

            if (this.streaming) {
                this.inflate(ctx, this.cumulation.readSlice(length));
                continue;
            }

            // 原版帧连长度前缀原样交给 splitter;拷一份,cumulation 之后要压缩回收,不能把切片交出去
            final int end = this.cumulation.readerIndex() + length;
            this.cumulation.readerIndex(start);
            ctx.fireChannelRead(this.cumulation.readBytes(end - start));
            if (this.enablePending) {
                this.enablePending = false;
                this.streaming = true;
            }
            if (this.giveUpPending && !this.streaming) {
                this.removeSelf(ctx);
                return;
            }
        }
    }

    private void inflate(final ChannelHandlerContext ctx, final ByteBuf frame) throws DataFormatException {
        this.inflater.setInput(frame.nioBuffer());
        final ByteBuf out = ctx.alloc().directBuffer(Math.max(CHUNK, frame.readableBytes() * 4));
        try {
            // 输出没填满且输入已吃完,这一帧就全出来了(SYNC_FLUSH 保证);填满了说明可能还有,扩容接着要
            while (true) {
                out.ensureWritable(CHUNK);
                final int space = out.writableBytes();
                final int produced = this.inflater.inflate(out.internalNioBuffer(out.writerIndex(), space));
                out.writerIndex(out.writerIndex() + produced);
                if (out.readableBytes() > MAX_INFLATED) throw new CorruptedFrameException("NetSqueeze 帧解压后过大");
                if (this.inflater.finished() || this.inflater.needsDictionary()) throw new CorruptedFrameException("NetSqueeze 压缩流异常结束");
                if (produced < space && this.inflater.needsInput()) break;
                if (produced == 0) throw new CorruptedFrameException("NetSqueeze 压缩流卡住");
            }

            final ChannelHandlerContext target = packetTarget(ctx);
            while (out.isReadable()) {
                final int length = readVarInt(out);
                if (length < 0 || length > out.readableBytes()) throw new CorruptedFrameException("NetSqueeze 帧里有半个包");
                if (length > CompressionDecoder.MAXIMUM_UNCOMPRESSED_LENGTH) throw new CorruptedFrameException("NetSqueeze 包过大: " + length);
                target.fireChannelRead(out.readRetainedSlice(length));
            }
        } finally {
            out.release();
        }
    }

    /** 包要直接进 decoder:从 decompress 的 context 往下发就跳过了它和 splitter;没开压缩时没有 decompress */
    private static ChannelHandlerContext packetTarget(final ChannelHandlerContext ctx) {
        final ChannelHandlerContext decompress = ctx.pipeline().context(HandlerNames.DECOMPRESS);
        if (decompress != null) return decompress;
        final ChannelHandlerContext splitter = ctx.pipeline().context(HandlerNames.SPLITTER);
        return splitter != null ? splitter : ctx;
    }

    /** 服务端不认握手:剩下的字节(可能是半帧)交还 splitter,自己摘掉 */
    private void removeSelf(final ChannelHandlerContext ctx) {
        this.removed = true;
        final ByteBuf rest = this.cumulation;
        this.cumulation = null;
        ctx.pipeline().remove(this);
        if (rest.isReadable()) {
            ctx.fireChannelRead(rest);
            return;
        }
        rest.release();
    }

    private void compact() {
        if (this.cumulation == null) return;
        if (!this.cumulation.isReadable()) {
            this.cumulation.release();
            this.cumulation = null;
            return;
        }
        this.cumulation.discardSomeReadBytes();
    }

    /** 读一个 varint;字节不够返回 -1(读指针位置由调用方复原) */
    private static int readVarInt(final ByteBuf buf) {
        int value = 0;
        for (int i = 0; i < 5; i++) {
            if (!buf.isReadable()) return -1;
            final byte b = buf.readByte();
            value |= (b & 0x7F) << (7 * i);
            if ((b & 0x80) == 0) return value;
        }
        throw new CorruptedFrameException("NetSqueeze varint 过长");
    }
}

package me.albert.netsqueeze.client;

import io.netty.channel.ChannelHandlerContext;
import io.netty.channel.ChannelInboundHandlerAdapter;
import net.minecraft.network.protocol.common.ClientboundCustomPayloadPacket;
import net.minecraft.network.protocol.configuration.ClientboundFinishConfigurationPacket;

/**
 * 挂在 packet_handler 前面,看的是解好的包对象,和 {@link StreamDecoder} 同一次 channelRead 里同步跑:
 * 解码器交出 enable 这一帧、等它返回时,这里已经置好位,解码器接着就按新格式解剩下的字节。
 * <ul>
 *   <li>收到 {@code netsqueeze:enable}:通知解码器切换,吞掉这个包,摘掉自己;</li>
 *   <li>配置阶段结束还没等到:服务端没装插件,通知解码器撤掉,摘掉自己。</li>
 * </ul>
 */
final class EnableDetector extends ChannelInboundHandlerAdapter {

    static final String NAME = "netsqueeze_detect";

    @Override
    public void channelRead(final ChannelHandlerContext ctx, final Object msg) {
        if (msg instanceof ClientboundCustomPayloadPacket packet && packet.payload().type().id().equals(NetSqueezeClient.ENABLE)) {
            final StreamDecoder decoder = decoder(ctx);
            ctx.pipeline().remove(this);
            if (decoder == null) {
                // 不该发生(没解码器就不会发 hello);服务端已经切了,这边解不了,只能断开
                throw new IllegalStateException("NetSqueeze: 收到 enable 但解码器不在管线里");
            }
            decoder.enable();
            NetSqueezeClient.LOGGER.info("服务器已启用流式压缩");
            return;
        }
        if (msg instanceof ClientboundFinishConfigurationPacket) {
            final StreamDecoder decoder = decoder(ctx);
            ctx.pipeline().remove(this);
            if (decoder != null) decoder.giveUp();
        }
        ctx.fireChannelRead(msg);
    }

    private static StreamDecoder decoder(final ChannelHandlerContext ctx) {
        return (StreamDecoder) ctx.pipeline().get(StreamDecoder.NAME);
    }
}

package me.albert.netsqueeze.client;

import io.netty.channel.Channel;
import io.netty.channel.ChannelPipeline;
import me.albert.netsqueeze.client.mixin.ConnectionAccessor;
import net.minecraft.network.Connection;
import net.minecraft.network.HandlerNames;
import net.minecraft.network.protocol.common.ServerboundCustomPayloadPacket;
import net.minecraft.network.protocol.common.custom.DiscardedPayload;
import net.minecraft.resources.Identifier;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * 和服务端插件(NetSqueeze 的 stream 包)的握手约定,两边改协议时一起改 {@link #VERSION}:
 * <ol>
 *   <li>进配置阶段时发 {@code netsqueeze:hello_v<版本>},不带数据(原版 DiscardedPayload 不带数据,版本只能编进频道名,
 *       这样不用依赖 Fabric API 注册载荷类型);</li>
 *   <li>服务端认得就回 {@code netsqueeze:enable},这是最后一个原版格式的包,之后全是流式压缩的帧,
 *       由 {@link StreamDecoder} 在 netty 线程上当场切换解码;服务端不认得就什么都不回,配置阶段结束时撤掉解码器。</li>
 * </ol>
 * 上行不动,照走原版。
 */
public final class NetSqueezeClient {

    public static final Logger LOGGER = LoggerFactory.getLogger("NetSqueeze");

    static final int VERSION = 1;

    static final Identifier HELLO = Identifier.fromNamespaceAndPath("netsqueeze", "hello_v" + VERSION);

    static final Identifier ENABLE = Identifier.fromNamespaceAndPath("netsqueeze", "enable");

    private NetSqueezeClient() {
    }

    /** 连接刚建好、还没收到任何字节时调:解码器挂在 splitter 前面,检测器挂在 packet_handler 前面 */
    public static void install(final ChannelPipeline pipeline) {
        if (pipeline.get(HandlerNames.SPLITTER) == null || pipeline.get(HandlerNames.PACKET_HANDLER) == null) return;
        pipeline.addBefore(HandlerNames.SPLITTER, StreamDecoder.NAME, new StreamDecoder());
        pipeline.addBefore(HandlerNames.PACKET_HANDLER, EnableDetector.NAME, new EnableDetector());
    }

    /**
     * 正版服登录时原版把 decrypt 插在 splitter 前面,正好夹在解码器和 splitter 中间,解码器就会看到密文,得挪到 decrypt 后面。
     * 这时服务端在等加密回应,不会有新字节进来,换个新实例不丢东西(本服是离线模式,走不到这里)
     */
    public static void moveAfterDecrypt(final ChannelPipeline pipeline) {
        if (pipeline.get(HandlerNames.DECRYPT) == null || pipeline.get(StreamDecoder.NAME) == null) return;
        pipeline.remove(StreamDecoder.NAME);
        pipeline.addAfter(HandlerNames.DECRYPT, StreamDecoder.NAME, new StreamDecoder());
    }

    /** 登录完成、出站已切到配置协议后调;解码器没挂上(内存连接等)就不发,否则服务端一切换这边就解不了 */
    public static void sendHello(final Connection connection) {
        final Channel channel = ((ConnectionAccessor) connection).netsqueeze$getChannel();
        if (channel == null || channel.pipeline().get(StreamDecoder.NAME) == null) return;
        connection.send(new ServerboundCustomPayloadPacket(new DiscardedPayload(HELLO)));
    }
}

package me.albert.netsqueeze.client.mixin;

import me.albert.netsqueeze.client.NetSqueezeClient;
import net.minecraft.client.multiplayer.ClientHandshakePacketListenerImpl;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.login.ClientboundLoginFinishedPacket;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

@Mixin(ClientHandshakePacketListenerImpl.class)
public abstract class ClientHandshakePacketListenerImplMixin {

    @Shadow
    @Final
    private Connection connection;

    /** 原版在这里切到配置协议并发 brand,TAIL 时出站已是配置协议,紧跟着发 hello */
    @Inject(method = "handleLoginFinished", at = @At("TAIL"))
    private void netsqueeze$hello(final ClientboundLoginFinishedPacket packet, final CallbackInfo ci) {
        NetSqueezeClient.sendHello(this.connection);
    }
}

package me.albert.netsqueeze.client.mixin;

import io.netty.channel.Channel;
import net.minecraft.network.Connection;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.gen.Accessor;

@Mixin(Connection.class)
public interface ConnectionAccessor {

    @Accessor("channel")
    Channel netsqueeze$getChannel();
}

package me.albert.netsqueeze.client.mixin;

import io.netty.channel.Channel;
import io.netty.channel.ChannelPipeline;
import javax.crypto.Cipher;
import me.albert.netsqueeze.client.NetSqueezeClient;
import net.minecraft.network.Connection;
import net.minecraft.network.protocol.PacketFlow;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

@Mixin(Connection.class)
public abstract class ConnectionMixin {

    @Shadow
    private Channel channel;

    @Shadow
    public abstract PacketFlow getReceiving();

    /** 连接刚建好(splitter、packet_handler 都在,还没收任何字节)时挂上解码器;只管客户端这头,内存连接没有 splitter 会跳过 */
    @Inject(method = "configurePacketHandler", at = @At("TAIL"))
    private void netsqueeze$install(final ChannelPipeline pipeline, final CallbackInfo ci) {
        if (this.getReceiving() != PacketFlow.CLIENTBOUND) return;
        NetSqueezeClient.install(pipeline);
    }

    @Inject(method = "setEncryptionKey", at = @At("TAIL"))
    private void netsqueeze$afterEncryption(final Cipher decryptCipher, final Cipher encryptCipher, final CallbackInfo ci) {
        if (this.getReceiving() != PacketFlow.CLIENTBOUND) return;
        NetSqueezeClient.moveAfterDecrypt(this.channel.pipeline());
    }
}
